69	// edge 自身字段键（用于识别折线块何时结束）
70	bool IsEdgeFieldKey(const std::string& line) {
71	  return ValueAfterColon(line, "from").has_value() ||
72	         ValueAfterColon(line, "to").has_value() ||
73	         ValueAfterColon(line, "distance_m").has_value() ||
74	         ValueAfterColon(line, "distance").has_value() ||
75	         ValueAfterColon(line, "bidirectional").has_value() ||
76	         ValueAfterColon(line, "enabled").has_value();
77	}
