679	StationCatalogReloader::StationCatalogReloader(std::filesystem::path path)
680	    : path_(std::move(path)),
681	      watcher_(path_.string(), [this](const YAML::Node&) { TryLoad(true); }) {
682	  TryLoad(false);   // 初始加载等价节点 on_configure 的一次性读取
683	  watcher_.Tick();  // 建立 mtime 基线：首拍只记基线不回调，之后的变化才重载
684	}
685	
686	bool StationCatalogReloader::Tick() {
687	  const auto before = reload_count_;
688	  watcher_.Tick();
689	  if (!watcher_.last_error().empty()) {
690	    last_error_ = watcher_.last_error();  // YAML 解析失败：回调未触发，旧目录保持
691	  }
692	  return reload_count_ > before;
693	}
694	
695	std::string StationCatalogReloader::last_error() const {
696	  return last_error_;
697	}
