699	void StationCatalogReloader::TryLoad(bool count_as_reload) {
700	  if (auto loaded = LoadStationCatalog(path_)) {
701	    catalog_ = std::move(*loaded);
702	    loaded_ = true;
703	    if (count_as_reload) {
704	      ++reload_count_;
705	    }
706	    last_error_.clear();
707	  } else {
708	    // 校验失败（空目录、重复 id、非法位姿等）：保留旧目录，记录错误
709	    last_error_ = "station catalog invalid or unreadable: " + path_.string();
710	  }
