61	  void LoadStations(const std::string& filepath) {
62	    try {
63	      YAML::Node root = YAML::LoadFile(filepath);
64	      if (root["stations"]) {
65	        for (const auto& node : root["stations"]) {
66	          StationInfo st;
67	          st.id = node["id"].as<std::string>();
68	          st.x = node["x"].as<double>();
69	          st.y = node["y"].as<double>();
70	          st.yaw = node["yaw"].as<double>(0.0);
71	          st.type = node["type"].as<std::string>("station");
72	          stations_[st.id] = st;
73	        }
74	      }
75	      RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s", stations_.size(), filepath.c_str());
76	    } catch (const std::exception& e) {
77	      RCLCPP_WARN(get_logger(), "Failed to load stations YAML: %s, using defaults", e.what());
78	      // 默认提供基准拓扑站点
79	      stations_["station_pickup_A"] = {"station_pickup_A", 1.0, 2.0, 0.0, "pickup"};
