### Map callback pipeline

```cpp
void MapIngestNode::MapCallback(const OccupancyGrid::SharedPtr msg) {
  if (msg->info.width == 0 || msg->info.height == 0) {
    RCLCPP_WARN(get_logger(), "Ignoring empty map (%u x %u)", ...);
    return;
  }
  if (msg->data.size() != static_cast<size_t>(width) * height) { warn; return; }

  MapGrid grid;
  grid.width = msg->info.width;
  grid.height = msg->info.height;
  grid.resolution = msg->info.resolution;
  grid.origin_x = msg->info.origin.position.x;
  grid.origin_y = msg->info.origin.position.y;
  grid.origin_yaw = YawFromQuaternion(msg->info.origin.orientation.z, msg->info.origin.orientation.w);
  grid.data.assign(msg->data.begin(), msg->data.end());

  auto anchors = LoadAnchors();
  if (anchors.empty()) {
    RCLCPP_ERROR(get_logger(), "No station anchors loaded (markers_file: '%s'); waiting for a valid markers file before generating catalog", ...);
    return;
  }

  SafetyFilterConfig safety_cfg;
  safety_cfg.robot_radius_m = robot_radius_m_;
  safety_cfg.safety_margin_m = safety_margin_m_;

  PruneConfig prune_cfg;
  prune_cfg.min_branch_length_m = min_branch_length_m_;
  prune_cfg.resolution = grid.resolution;

  TopologyBuilderConfig builder_cfg;
  builder_cfg.max_snap_dist_m = max_snap_dist_m_;
  builder_cfg.map_hash = ComputeMapHash(grid);
  builder_cfg.graph_version = "v1";

  const auto safety_grid = FilterSafetySpace(grid, safety_cfg);
  const auto skeleton = ZhangSuenThinning(safety_grid);
  std::vector<PixelCoord> protected_points;
  protected_points.reserve(anchors.size());
  for (const auto& anchor : anchors) {
    protected_points.push_back(WorldToPixel(WorldCoord{anchor.x, anchor.y}, grid));
  }
  const auto pruned = PruneSkeletonProtected(skeleton, protected_points, prune_cfg);

  const auto result = BuildTopologyCatalog(pruned, grid, anchors, builder_cfg);
  if (!result.success) {
    RCLCPP_ERROR(get_logger(), "Map ingest failed: %s (keeping existing catalog)", result.error_message.c_str());
    return;
  }
  if (!WriteCatalogAtomic(result.catalog)) {
    RCLCPP_ERROR(get_logger(), "Failed to write catalog to %s (keeping existing catalog)", ...);
    return;
  }
  last_map_hash_ = builder_cfg.map_hash;
  RCLCPP_INFO(get_logger(), "Successfully ingested map and generated %s (%zu stations, %zu road nodes, %zu edges)", ...);
  if (publish_markers_) PublishTopologyMarkers(result.catalog);
}
```

### WriteCatalogAtomic

```cpp
bool MapIngestNode::WriteCatalogAtomic(const StationCatalog& catalog) const {
  const std::filesystem::path final_path(output_stations_file_);
  const std::filesystem::path tmp_path = final_path.string() + ".tmp";
  std::error_code ec;
  if (final_path.has_parent_path()) {
    std::filesystem::create_directories(final_path.parent_path(), ec);
    if (ec) { error; return false; }
  }
  {
    std::ofstream out(tmp_path);
    if (!out) return false;
    out << SerializeCatalog(catalog);
    out.flush();
    if (!out) { out.close(); remove tmp; return false; }
  }
  // 回读校验：tmp 文件必须能被调度侧 LoadStationCatalog 严格解析
  if (!amr_dispatcher_core::catalog::LoadStationCatalog(tmp_path)) {
    std::filesystem::remove(tmp_path, ec);
    RCLCPP_ERROR? — const method can't log with get_logger? get_logger() is const? rclcpp::Node::get_logger() const → yes const.
    return false;
  }
  std::filesystem::rename(tmp_path, final_path, ec);
  if (ec) { remove tmp; return false; }
  return true;
}
```

